/**
 * How a written test finds an element on the phone: the best stable name the app gives it, never its position on the screen and never an
 * absolute XPath.
 *
 * The main locator, in this order (the first one that names exactly this element on the screen it was seen on):
 *   1. the resource id, when it looks designed: not generated by an optimizer ("a1", "b2c"), not one of a numbered list ("row_1", "row_2"),
 *      not a framework default ("text1"). A Jetpack Compose test tag is a resource id too;
 *   2. the accessibility label (content-desc), when it does not change by itself;
 *   3. the exact visible text (a field's hint), when it is a static label: not a count, a time, a price or a long piece of feed content;
 *   4. role plus name, when the element's class is one Taqwright's getByRole names exactly (Button, EditText, Switch);
 *   5. the best of these names shared with other elements, made exact with the element's number among them.
 * An element with no name at all gets no locator, and a test that needs it is dropped with a reason.
 *
 * Then up to three FALLBACKS (spec LocatorFallbackSchema), tried in order at run time when the main locator finds nothing, each checked to
 * name exactly this element on the recorded screen: the other names above, then UiSelector combinations (resource id + text, class + text or
 * label, or a name inside a stable ancestor such as the toolbar or a list), then a relative XPath anchored on a stable ancestor.
 */
import type { ScreenElement } from "../device/types.js";
import { MAX_LOCATOR_FALLBACKS, type Locator, type LocatorFallback } from "../../spec/schema.js";

type Named = Pick<ScreenElement, "cls" | "text" | "desc" | "id" | "editable" | "password"> & Partial<Pick<ScreenElement, "scopes" | "inScroll" | "bareId" | "bounds">>;

/** Ids that say nothing about the element (a framework default or a counter). */
const GENERIC_ID = /^(text|title|label|image|icon|button|btn|view|container|content|root|frame|layout|item|row|cell|list|scroll|recycler|textview|imageview|edittext)\d*$/i;

/** Names an optimizer gives resources when it shrinks an app (R8, ProGuard): "a", "b2", "b2c", "a0b1". */
export function isObfuscatedId(id: string): boolean {
    return id.length <= 2 || (id.length <= 4 && /\d/.test(id) && !/[_-]/.test(id));
}

export function isStableId(id: string): boolean {
    return /^[A-Za-z][A-Za-z0-9_-]{2,99}$/.test(id) && !/\d{3,}/.test(id) && !GENERIC_ID.test(id) && !isObfuscatedId(id);
}

const LIST_ID = /^(.*?[A-Za-z_-])(\d{1,2})$/;

/** An id numbered like the rows of a list ("product_1" next to "product_2" on the same screen): it names a position, not a thing. */
export function isListId(id: string, all: readonly Pick<ScreenElement, "id">[]): boolean {
    const m = LIST_ID.exec(id);
    if (!m) return false;
    return all.some((x) => x.id !== id && LIST_ID.exec(x.id)?.[1] === m[1]);
}

/** Relative times, counts of things and other words around numbers that change by themselves ("5 min ago", "12 likes", "3 new"). */
const CHANGING = [
    /\b\d+\s*(s|sec|secs|m|min|mins|h|hr|hrs|d|w|wk|wks|mo|y|yr|yrs)\b/i,
    /\b(ago|yesterday|today|just now)\b/i,
    /\d[\d,.]*\s*[kKmM]?\+?\s*(likes?|comments?|reposts?|shares?|followers?|following|connections?|views?|reactions?|notifications?|messages?|new|unread|items?|results?|members?|people|posts?|jobs?|applicants?|mutual)\b/i,
    /^[\d,.]+\s*[kKmM]?\+?$/,
];

/** Text that changes by itself (counts, times, prices): useless to find or check an element. */
export function isDynamicText(t: string): boolean {
    const s = t.trim();
    if (!s) return true;
    const digits = (s.match(/\d/g) ?? []).length;
    if (digits > 0 && digits * 2 >= s.replace(/\s/g, "").length) return true;
    return digits > 0 && CHANGING.some((re) => re.test(s));
}

/** Longest text kept as a name: longer text inside a list is content (a post, a description), not a label. */
const MAX_LABEL_IN_LIST = 40;

const ROLES: Array<[RegExp, string]> = [
    [/^(Button|ImageButton|MaterialButton|AppCompatButton|FloatingActionButton|ExtendedFloatingActionButton)$/, "button"],
    [/^(EditText|TextInputEditText|AutoCompleteTextView|AppCompatEditText|SearchView)$/, "textbox"],
    [/^(CheckBox|AppCompatCheckBox|MaterialCheckBox)$/, "checkbox"],
    [/^(Switch|SwitchCompat|SwitchMaterial|MaterialSwitch|ToggleButton)$/, "switch"],
    [/^(RadioButton|AppCompatRadioButton)$/, "radio"],
    [/^(Spinner|AppCompatSpinner)$/, "combobox"],
    [/^(ImageView|AppCompatImageView)$/, "img"],
    [/^(TabView|Tab)$/, "tab"],
];

export function roleOf(cls: string): string | undefined {
    return ROLES.find(([re]) => re.test(cls))?.[1];
}

/** The classes Taqwright's getByRole looks up for a role on Android: a role locator is chosen only when the element has exactly that class. */
const TAQWRIGHT_ROLE_CLASS: Record<string, string> = { button: "Button", textbox: "EditText", switch: "Switch" };

const key = (v: string) => v.trim().toLowerCase();

/** A name worth finding the element by: present, not changing by itself, not a long piece of list content. */
function usableName(t: string, e: Named): boolean {
    return Boolean(t.trim()) && !isDynamicText(t) && !(e.inScroll && t.trim().length > MAX_LABEL_IN_LIST);
}

/** The id an element is found by, or "" (unstable, or numbered like a list's rows). */
function goodId(e: Named, all: readonly Named[]): string {
    return e.id && isStableId(e.id) && !isListId(e.id, all) ? e.id : "";
}

/**
 * A row of a list or a card with no name of its own (or one its siblings share): the element inside it with a name nothing else on the screen
 * has ("Product Designer" in a job's row). Tapping that text taps the row, as a finger would.
 */
function innerName(e: Named, all: readonly Named[]): { el: Named; loc: Locator } | undefined {
    if (!e.bounds) return undefined;
    const [l, t, r, b] = e.bounds;
    const inside = all.filter((x) => x !== e && x.bounds && x.bounds[0] >= l && x.bounds[1] >= t && x.bounds[2] <= r && x.bounds[3] <= b && !x.editable && !x.password);
    for (const x of inside) {
        const text = x.text.trim();
        if (usableName(text, x) && all.filter((y) => !y.password && key(y.text) === key(text)).length === 1) return { el: x, loc: { by: "text", value: text } };
    }
    for (const x of inside) {
        const desc = x.desc.trim();
        if (usableName(desc, x) && all.filter((y) => key(y.desc) === key(desc)).length === 1) return { el: x, loc: { by: "label", value: desc } };
    }
    return undefined;
}

/** The locator for `e`, judged against everything on the screen it was seen on (no fallbacks: see `locatorFor`). */
export function chooseLocator(e: Named, all: readonly Named[]): { loc?: Locator; note?: string; /** The element inside `e` whose name the locator uses. */ inner?: Named } {
    const same = (pick: (x: Named) => string, value: string) => all.filter((x) => key(pick(x)) === key(value));
    const nth = (list: Named[]) => list.indexOf(e);
    const make = (by: Locator["by"], value: string, list: Named[], extra: Partial<Locator> = {}): Locator =>
        list.length > 1 ? { by, value, ...extra, nth: Math.max(0, nth(list)) } : { by, value, ...extra };
    const id = goodId(e, all);

    if (id) {
        const list = same((x) => x.id, id);
        // Lists repeat their rows' ids: then a more specific name is better than a number.
        if (list.length <= 1) return { loc: { by: "testId", value: id } };
    }
    const desc = e.desc.trim();
    const descOk = usableName(desc, e);
    if (descOk) {
        const list = same((x) => x.desc, desc);
        if (list.length === 1) return { loc: { by: "label", value: desc } };
    }
    const text = e.password ? "" : e.text.trim();
    const textOk = usableName(text, e);
    if (textOk) {
        const list = same((x) => (x.password ? "" : x.text), text);
        if (list.length === 1) return { loc: e.editable ? { by: "placeholder", value: text } : { by: "text", value: text } };
    }
    const role = roleOf(e.cls);
    const name = descOk ? desc : textOk ? text : "";
    if (role && name && TAQWRIGHT_ROLE_CLASS[role] === e.cls) {
        const list = all.filter((x) => x.cls === e.cls && key(x.desc || (x.password ? "" : x.text)) === key(name));
        if (list.length === 1) return { loc: { by: "role", role, value: name } };
    }
    // A row or card without a name of its own: the name of what is inside it.
    const inner = innerName(e, all);
    if (inner) return { loc: inner.loc, inner: inner.el, note: "Found by the name of what is inside it." };
    // Several elements share the best name: say which one of them, counting in reading order.
    const shared = "Shares its name with other elements, so it is found by its number among them.";
    if (id) return { loc: make("testId", id, same((x) => x.id, id)), note: shared };
    if (descOk) return { loc: make("label", desc, same((x) => x.desc, desc)), note: shared };
    if (textOk) return { loc: make(e.editable ? "placeholder" : "text", text, same((x) => (x.password ? "" : x.text), text)), note: shared };
    return { note: "Has no name a test can use." };
}

// ── fallbacks ──────────────────────────────────────────────────────────────

/** A string inside a UiSelector expression (Java-like literal). */
const uiStr = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
/** An XPath 1.0 literal: XPath has no escapes, so a value with both quote kinds is written with concat(). */
export function xpathLiteral(s: string): string {
    if (!s.includes('"')) return `"${s}"`;
    if (!s.includes("'")) return `'${s}'`;
    return `concat(${s
        .split('"')
        .map((p, i) => [...(i > 0 ? [`'"'`] : []), ...(p ? [`"${p}"`] : [])])
        .flat()
        .join(", ")})`;
}
const SAFE_ID = /^[A-Za-z][A-Za-z0-9_-]{0,99}$/;
const SAFE_CLASS = /^[A-Za-z][A-Za-z0-9_]{0,59}$/;

/** UiSelector parts. A resource id is matched with or without its `package:id/` prefix (a Compose test tag has none). */
const ui = {
    id: (id: string) => `resourceIdMatches(${uiStr(`(.*:id/)?${id}`)})`,
    exactId: (id: string) => `resourceId(${uiStr(id)})`,
    text: (t: string) => `text(${uiStr(t)})`,
    desc: (d: string) => `description(${uiStr(d)})`,
    cls: (c: string) => `classNameMatches(${uiStr(`.*[.]${c}`)})`,
};
const sel = (parts: string[]) => `new UiSelector().${parts.join(".")}`;

/** XPath predicates (Appium's page source: `resource-id` with the package prefix, `class` with the full class name). */
const xp = {
    id: (id: string) => `[@resource-id=${xpathLiteral(id)} or substring-after(@resource-id, ":id/")=${xpathLiteral(id)}]`,
    text: (t: string) => `[@text=${xpathLiteral(t)}]`,
    desc: (d: string) => `[@content-desc=${xpathLiteral(d)}]`,
    cls: (c: string) => `[substring(@class, string-length(@class) - ${c.length})=${xpathLiteral(`.${c}`)}]`,
};

interface Way {
    way: LocatorFallback;
    /** The elements of the recorded screen it names. */
    hits: Named[];
}

const under = (x: Named, scope: string) => (x.scopes ?? []).includes(scope);

/**
 * Every way to find `e` that names exactly it on the recorded screen (a number among same-named ones only where said), best first. The
 * primary locator's own way is left out by the caller.
 */
function waysFor(e: Named, all: readonly Named[]): Way[] {
    const out: Way[] = [];
    const add = (way: LocatorFallback, hits: Named[]) => {
        if (way.value.length > 500 || /[\u0000-\u001f\u2028\u2029]/.test(way.value)) return;
        if (hits.length === 1 && hits[0] === e) out.push({ way, hits });
    };
    const textOf = (x: Named) => (x.password ? "" : x.text.trim());
    const id = goodId(e, all);
    const desc = e.desc.trim();
    const text = textOf(e);
    const descOk = usableName(desc, e);
    const textOk = usableName(text, e) && !e.password;
    const named = (x: Named, t: string, d: string) => (t && key(textOf(x)) === key(t)) || (d && key(x.desc) === key(d));

    if (id) add({ by: "testId", value: id }, all.filter((x) => x.id === id));
    // A Compose test tag is found as it is: Appium's id lookup adds the app's package in front, which a test tag does not have.
    if (id && e.bareId) add({ by: "uiSelector", value: sel([ui.exactId(id)]) }, all.filter((x) => x.id === id));
    if (descOk) add({ by: "label", value: desc }, all.filter((x) => key(x.desc) === key(desc)));
    if (textOk) add(e.editable ? { by: "placeholder", value: text } : { by: "text", value: text }, all.filter((x) => key(textOf(x)) === key(text) && (!e.editable || x.editable)));
    const role = roleOf(e.cls);
    const name = descOk ? desc : textOk ? text : "";
    if (role && name && TAQWRIGHT_ROLE_CLASS[role] === e.cls) add({ by: "role", role, value: name }, all.filter((x) => x.cls === e.cls && key(x.desc || textOf(x)) === key(name)));
    // UiSelector combinations: the (repeated) id with the text, the class with the text or the label.
    const rowId = e.id && SAFE_ID.test(e.id) && !isObfuscatedId(e.id) ? e.id : "";
    if (rowId && textOk) add({ by: "uiSelector", value: sel([ui.id(rowId), ui.text(text)]) }, all.filter((x) => x.id === rowId && key(textOf(x)) === key(text)));
    if (rowId && descOk) add({ by: "uiSelector", value: sel([ui.id(rowId), ui.desc(desc)]) }, all.filter((x) => x.id === rowId && key(x.desc) === key(desc)));
    if (SAFE_CLASS.test(e.cls) && (textOk || descOk))
        add({ by: "uiSelector", value: sel([ui.cls(e.cls), textOk ? ui.text(text) : ui.desc(desc)]) }, all.filter((x) => x.cls === e.cls && (textOk ? key(textOf(x)) === key(text) : key(x.desc) === key(desc))));
    // Inside a stable ancestor (nearest first): by name, else by class when it is the only one of its class there.
    const anchors = [...(e.scopes ?? [])].reverse().filter((s) => isStableId(s) && s !== e.id && SAFE_ID.test(s));
    const anchorWays: Way[] = [];
    for (const s of anchors) {
        const inside = all.filter((x) => under(x, s));
        if (textOk || descOk) {
            const t = textOk ? text : "";
            const d = textOk ? "" : desc;
            const hits = inside.filter((x) => named(x, t, d));
            if (hits.length === 1 && hits[0] === e) {
                anchorWays.push({ way: { by: "uiSelector", value: `${sel([ui.id(s)])}.childSelector(${sel([t ? ui.text(t) : ui.desc(d)])})` }, hits });
                anchorWays.push({ way: { by: "xpath", value: `//*${xp.id(s)}//*${t ? xp.text(t) : xp.desc(d)}` }, hits });
                break;
            }
        }
        if (SAFE_CLASS.test(e.cls)) {
            const hits = inside.filter((x) => x.cls === e.cls);
            if (hits.length === 1 && hits[0] === e) {
                anchorWays.push({ way: { by: "uiSelector", value: `${sel([ui.id(s)])}.childSelector(${sel([ui.cls(e.cls)])})` }, hits });
                anchorWays.push({ way: { by: "xpath", value: `//*${xp.id(s)}//*${xp.cls(e.cls)}` }, hits });
                break;
            }
        }
    }
    for (const w of anchorWays) add(w.way, w.hits);
    return out;
}

const sameWay = (a: LocatorFallback | Locator, b: LocatorFallback | Locator) => a.by === b.by && (a.value ?? "") === (b.value ?? "") && (a.role ?? "") === (b.role ?? "") && (a.nth ?? -1) === (b.nth ?? -1);

/**
 * Up to three fallbacks for `primary`, best first, keeping at least one that does not depend on the element's own names (an anchored
 * UiSelector or XPath) when there is one: when the app renames the element, that is the one still standing.
 */
export function fallbacksFor(e: Named, all: readonly Named[], primary: Locator | undefined): LocatorFallback[] {
    const ways = waysFor(e, all)
        .map((w) => w.way)
        .filter((w) => !primary || !sameWay(w, primary));
    const unique = ways.filter((w, i) => ways.findIndex((x) => sameWay(x, w)) === i);
    const picked = unique.slice(0, MAX_LOCATOR_FALLBACKS);
    const anchored = (w: LocatorFallback) => w.by === "xpath" || (w.by === "uiSelector" && w.value.includes(".childSelector("));
    const structural = unique.find(anchored) ?? unique.find((w) => w.by === "uiSelector");
    if (structural && !picked.includes(structural)) picked[picked.length - 1] = structural;
    return picked;
}

/** The locator a written test uses for `e`: the main one with its checked fallbacks. Undefined: the element has no name a test can use. */
export function locatorFor(e: Named, all: readonly Named[]): { loc?: Locator; note?: string } {
    const { loc, note, inner } = chooseLocator(e, all);
    if (!loc) return { ...(note ? { note } : {}) };
    const fallbacks = fallbacksFor(inner ?? e, all, loc);
    return { loc: fallbacks.length ? { ...loc, fallbacks } : loc, ...(note ? { note } : {}) };
}

/**
 * The same element as a UiSelector expression, for scrolling a list until it shows (Taqwright wraps it in a UiScrollable). Undefined when the
 * locator cannot be said that way (a field's hint, a CSS selector, a value built from test data).
 */
export function uiSelectorOf(l: Pick<Locator, "by" | "value" | "role">): string | undefined {
    const v = l.value ?? "";
    if (!v || v.includes("{{") || /[\u0000-\u001f\u2028\u2029]/.test(v) || v.length > 300) return undefined;
    switch (l.by) {
        case "testId":
            return SAFE_ID.test(v) ? sel([ui.id(v)]) : undefined;
        case "label":
            return sel([ui.desc(v)]);
        case "text":
            return sel([ui.text(v)]);
        case "role": {
            const cls = l.role ? TAQWRIGHT_ROLE_CLASS[l.role] : undefined;
            return cls ? `new UiSelector().className(${uiStr(`android.widget.${cls}`)}).${ui.text(v)}` : undefined;
        }
        default:
            return undefined;
    }
}
